for (const model of denverMetroDistrictModels) {
  const office = model.office;
  const flex = model.flex;
  districts[model.path] = {
    path: model.path,
    primary_archetype: model.primary,
    secondary_archetypes: model.secondary || [],
    commercial_thesis: model.thesis,
    best_fit_businesses: model.best,
    poor_fit_businesses: model.poor,
    compare_with: (model.compare || []).map(([district_name, district_path, reason]) => ({
      district_name,
      district_path,
      comparison_path: denverMetroComparisonPath(model.name, district_name),
      reason,
    })),
    office_profile: office ? {
      office_orientation: office[0],
      client_facing_strength: office[1],
      transit_orientation: office[2],
      walkability_context: office[3],
      building_scale: office[4],
      floorplate_pattern: "mixed",
      tenant_fit: office.slice(5),
      commute_pattern: ["denver_metro", "regional_access"],
    } : undefined,
    warehouse_flex_profile: flex ? {
      industrial_orientation: flex[0],
      truck_access: flex[1],
      highway_access: flex[2],
      port_airport_access: flex[3],
      loading_likelihood: flex[4],
      yard_parking_likelihood: flex[4],
      building_format: ["industrial_flex", "warehouse", "service_industrial", "rd_flex"],
      tenant_fit: flex.slice(5),
      decision_context: `${model.thesis} This market is most useful to compare when industrial/flex, logistics, R&D, aerospace, airport access, or regional operations geography matters.`,
    } : undefined,
    confidence_level: model.confidence_level || "medium",
    review_status: model.review_status || "generated",
  };
}

